from soar.commands.builtin import dispatch_builtin, dispatch_write
from soar.commands.http_command import invoke as http_invoke
from soar.commands.registry import validate_io
from soar.execution.background import run_background_job
from soar.execution.dispatch import raise_platform_alert
from soar.execution.policy import choose_executor, limits_for
from soar.execution.sandbox import run_isolated
from soar.platform.redact import looks_like_credential
from soar.playbooks.engine import finish_step
from soar.secrets.provider import lease_for_job

# Not every job is a playbook step. Feed fetches, ATT&CK syncs and
# connector probes are published onto the same stream and have no step to
# claim, so they are separated here before anything reads step_id.
if (job.get("kind") or "step") != "step":
    return run_background_job(db, provider, job)

org_id = job["org_id"]
step_id = job["step_id"]

if not db.claim_step(step_id, worker_id, org_id):
    return {"claimed": False, "reason": "already claimed or terminal"}

rows = db.query(
    "SELECT cv.kind, cv.implementation, cv.input_schema, cv.output_schema, "
    "cv.auth, cv.timeout_ms, cv.effect, c.trust_level, c.key, "
    "i.egress_allowlist, i.config "
    "FROM command_version cv JOIN command c ON c.id = cv.command_id "
    "LEFT JOIN integration i ON i.id = c.integration_id "
    "WHERE cv.id = %s", [job["command_version_id"]], org_id,
)
if not rows:
    return finish_step(db, org_id, step_id,
                       {"ok": False,
                        "error": {"error_class": "NOT_FOUND",
                                  "message": "command version missing"}})
command = rows[0]
inputs = job["inputs"]

try:
    validate_io(command["input_schema"], inputs, "input")
except ValueError as error:
    return finish_step(db, org_id, step_id,
                       {"ok": False,
                        "error": {"error_class": "VALIDATION", "message": str(error)}})

# Dry run: a read command runs for real, a mutating one returns its declared
# example and is never issued a credential lease. The guarantee is structural
# rather than behavioural - there is no credential to misuse.
if job.get("mode") == "dry_run" and command["effect"] == "mutating":
    return finish_step(db, org_id, step_id, {
        "ok": True, "dry_run": True,
        "output": command["implementation"].get("dry_run_example", {}),
        "logs": ["dry run: no credential leased, nothing was changed"],
    })

lease = {}
if command["trust_level"] != "untrusted" and command["auth"]:
    lease = lease_for_job(provider, org_id, command["auth"])

executor = choose_executor(command["trust_level"], command["kind"])
limits = limits_for(command["trust_level"], command["timeout_ms"])

try:
    if command["kind"] == "write":
        # Writes go through the same worker as everything else, but with a
        # database handle instead of a credential lease. Nothing here
        # leaves the box, so there is nothing to lease.
        result = {"ok": True,
                  "output": dispatch_write(db, org_id, command["key"], inputs)}
    elif executor == "in_process":
        result = {"ok": True, "output": dispatch_builtin(command["key"], inputs)}
    elif executor == "sandbox":
        result = run_isolated(command["implementation"]["source"], inputs, limits)
    elif command["kind"] == "http":
        # The integration's own settings travel with the implementation, so
        # the command definition stays vendor-generic and the part that
        # differs per client stays on the integration row.
        implementation = dict(command["implementation"])
        implementation["config"] = command["config"] or {}
        output = http_invoke(implementation, inputs, lease,
                             command["egress_allowlist"] or [],
                             command["timeout_ms"])
        result = {"ok": True, "output": output}
    else:
        result = run_isolated(command["implementation"].get("source", ""),
                              inputs, limits)
except PermissionError as error:
    result = {"ok": False,
              "error": {"error_class": "POLICY", "message": str(error)}}
except Exception as error:  # noqa: BLE001 - the class is on the error record
    result = {"ok": False,
              "error": {"error_class": "TRANSIENT", "message": str(error)}}
finally:
    lease = {}  # the lease does not outlive the job

if result.get("ok"):
    try:
        validate_io(command["output_schema"], result["output"], "output")
    except ValueError as error:
        result = {"ok": False,
                  "error": {"error_class": "VALIDATION", "message": str(error)}}

for line in result.get("logs", []):
    if looks_like_credential(str(line)):
        raise_platform_alert(db, org_id, "secret_shape_in_output",
                             {"step_id": step_id, "command": command["key"]})
        break

return finish_step(db, org_id, step_id, result)
